import { componentWrapperDecorator, type Decorator, type Preview } from '@storybook/angular';
import { setCompodocJson } from '@storybook/addon-docs/angular';
// Generated by compodoc before every Storybook run (see project.json).
// Feeds the autodocs API tables and component descriptions from the
// JSDoc on each design-system component.
import docJson from './documentation.json';

setCompodocJson(docJson);

// Reflect the toolbar choice onto <html data-theme="…"> — the design
// system's themes key off this attribute (explicit value always wins
// over the OS preference).
const withTheme: Decorator = (story, context) => {
  document.documentElement.setAttribute(
    'data-theme',
    context.globals['theme'] === 'dark' ? 'dark' : 'light',
  );
  return story();
};

// Some controls (Select, MultiSelect, …) render their popover inline as an
// absolutely-positioned panel rather than in a body-level overlay, so in a
// Docs example it escapes the example box. The example is styled non-clipping
// (see preview-head.html) so the panel shows in full, and the observer set up
// below grows the example to contain the open panel — pushing the following
// content down instead of overlapping it. This wrapper is the element it grows.
//
// Only content that can genuinely escape counts: see `neededHeight`.
const withExampleContainer = componentWrapperDecorator(
  (story) => `<div class="sb-example">${story}</div>`,
);

/**
 * Grows each `.sb-example` to contain its tallest descendant — including
 * an open, absolutely-positioned inline popover — so the following Docs
 * content is pushed down instead of overlapped, then reverts once it
 * closes. This lives here (not as an inline script in preview-head.html)
 * because Storybook injects that file via innerHTML, which does not
 * execute inline scripts; preview.ts is bundled and runs reliably.
 */
function setupExampleContainerObserver(doc: Document): void {
  /**
   * True when this element clips its content, so nothing inside it can spill
   * past the example however tall that content is.
   */
  const clipsContent = (el: Element): boolean => {
    const style = getComputedStyle(el);
    return style.overflowY !== 'visible' || style.overflowX !== 'visible';
  };

  /**
   * The distance from the example's top to the lowest point its content can
   * actually reach.
   *
   * Descends the tree rather than scanning every descendant flat, and stops at
   * any element that clips: its own box still counts, but what is inside it
   * cannot escape and so cannot need more room. A virtualized list is the case
   * that makes this matter — the datagrid's row canvas is as tall as the whole
   * dataset (44,000px for a thousand rows) inside a 404px scroll viewport, and
   * measuring it flat grew the example to the height of the canvas.
   */
  const neededHeight = (ex: HTMLElement): number => {
    const top = ex.getBoundingClientRect().top;
    let maxBottom = top;
    const visit = (parent: Element): void => {
      for (const child of Array.from(parent.children)) {
        const r = child.getBoundingClientRect();
        if ((r.width || r.height) && r.bottom > maxBottom) {
          maxBottom = r.bottom;
        }
        if (!clipsContent(child)) {
          visit(child);
        }
      }
    };
    visit(ex);
    return maxBottom - top;
  };

  const adjust = (ex: HTMLElement): void => {
    const current = parseFloat(ex.style.minHeight) || 0;
    const target = Math.ceil(Math.max(0, neededHeight(ex)));
    // Only write when it actually changes, so our own style mutation does
    // not retrigger the observer into a loop.
    if (Math.abs(target - current) > 1) {
      ex.style.minHeight = target ? `${target}px` : '';
    }
  };

  const pending = new Set<HTMLElement>();
  let frame = 0;
  const flush = (): void => {
    frame = 0;
    const list = [...pending];
    pending.clear();
    for (const ex of list) {
      if (ex.isConnected) {
        adjust(ex);
      }
    }
  };
  const schedule = (ex: HTMLElement): void => {
    pending.add(ex);
    frame ||= requestAnimationFrame(flush);
  };
  const scheduleClosest = (target: EventTarget | null): void => {
    if (target instanceof Element) {
      const ex = target.closest<HTMLElement>('.sb-example');
      if (ex) {
        schedule(ex);
      }
    }
  };

  new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      scheduleClosest(mutation.target);
    }
  }).observe(doc.body, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['style', 'class', 'hidden'],
  });

  // An opening popover animates in from a translated/scaled state, so its
  // measured box grows until the animation settles; re-measure once it
  // ends, otherwise the container is sized to the mid-animation box and the
  // settled popover spills past it.
  for (const type of ['animationend', 'transitionend']) {
    doc.body.addEventListener(
      type,
      (event) => {
        scheduleClosest(event.target);
      },
      true,
    );
  }

  for (const ex of Array.from(doc.querySelectorAll<HTMLElement>('.sb-example'))) {
    schedule(ex);
  }
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      setupExampleContainerObserver(document);
    });
  } else {
    setupExampleContainerObserver(document);
  }
}

const preview: Preview = {
  // Generate a Docs page for every component from its stories + JSDoc. The
  // stories are listed in the sidebar under their component, which the sidebar
  // collapses until the reader opens it.
  tags: ['autodocs'],
  parameters: {
    options: {
      storySort: {
        order: [
          'Foundations',
          ['Colour', 'Typography', 'Spacing', 'Elevation', 'Motion', 'Icons'],
          'Layout & Navigation',
          '*',
        ],
      },
    },
    // PrimeNG-style right-hand table of contents on each docs page.
    docs: { toc: true },
    controls: {
      matchers: { color: /(background|color)$/i, date: /Date$/ },
    },
  },
  globalTypes: {
    theme: {
      description: 'Color theme',
      toolbar: {
        title: 'Theme',
        icon: 'mirror',
        items: ['light', 'dark'],
        dynamicTitle: true,
      },
    },
  },
  initialGlobals: {
    theme: 'light',
  },
  decorators: [withExampleContainer, withTheme],
};

export default preview;
